import {
    Table,
    StringColumn,
    UserRolesColumn,
    BooleanColumn,
    ReferenceColumn,
    GenericColumn,
    BasicImageColumn,
    ListColumn,
    TranslatedTextColumn,
    DurationColumn,
    IntegerColumn,
    DecimalColumn,
    ChoiceColumn,
    GuidColumn,
} from '@servicenow/sdk/core'

export const sc_cat_item = Table({
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.synch_attachments': true,
        'all_tables.text_index_translations': true,
        global_search_config_handler: 'CatalogItem',
        kagami_csindex_enabled: true,
        text_wiki_translations: true,
        update_synch: true,
    },
    display: 'name',
    extends: 'sys_metadata',
    extensible: true,
    label: 'Catalog Item',
    name: 'sc_cat_item',
    schema: {
        state: StringColumn({
            dropdown: 'dropdown_with_none',
            label: 'State',
            readOnly: true,
            readOnlyOption: 'instance_configured',
        }),
        checked_out: StringColumn({
            dropdown: 'dropdown_with_none',
            label: 'Checked out',
            readOnly: true,
            readOnlyOption: 'instance_configured',
        }),
        access_type: StringColumn({
            attributes: {
                no_text_index: true,
            },
            default: 'restricted',
            dropdown: 'dropdown_without_none',
            label: 'Access Type',
        }),
        request_method: StringColumn({
            attributes: {
                no_text_index: true,
            },
            dropdown: 'dropdown_with_none',
            label: [
                {
                    label: 'Request method',
                    plural: 'Request methods',
                    language: 'en',
                    url: 'itsm_context_help.do?help_resource=CSHelp:Service_Catalog_Portal_Settings',
                },
            ],
        }),
        template_manager_roles: UserRolesColumn({
            attributes: {
                record_watcher_blacklist: true,
            },
            label: 'Template Manager roles',
        }),
        no_quantity_v2: BooleanColumn({
            label: 'Hide Quantity',
        }),
        no_save_as_draft: BooleanColumn({
            label: "Hide 'Save as Draft'",
        }),
        no_wishlist_v2: BooleanColumn({
            label: "Hide 'Add to Wish List'",
        }),
        sc_template: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Associated template',
            referenceTable: 'sc_template',
        }),
        published_ref: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Published item',
            readOnly: true,
            readOnlyOption: 'instance_configured',
            referenceTable: 'sc_cat_item',
        }),
        list_price: GenericColumn({
            columnType: 'currency',
            label: [
                {
                    hint: 'List price for this item, before any discounts are taken',
                    label: 'List Price',
                    plural: 'List Prices',
                    language: 'en',
                },
            ],
            maxLength: 20,
        }),
        price: GenericColumn({
            attributes: {
                omit_sys_original: true,
                serializer: 'com.glide.script.PriceXMLSerializer',
            },
            columnType: 'price',
            default: '0.00',
            label: 'Price',
            maxLength: 20,
        }),
        ignore_price: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Auto evaluated to prevent price calculations on items with no price (including variables)',
                    label: 'Ignore price',
                    plural: 'Ignore prices',
                    language: 'en',
                },
            ],
            readOnly: true,
            readOnlyOption: 'instance_configured',
        }),
        billable: BooleanColumn({
            label: 'Billable',
        }),
        image: BasicImageColumn({
            attributes: {
                no_text_index: true,
                pdf_cell_type: 'basic_image',
            },
            label: 'Image',
        }),
        category: ReferenceColumn({
            attributes: {
                ref_auto_completer: 'AJAXTableCompleter',
                ref_ac_columns: 'sc_catalog',
            },
            default: 'javascript: new SNCCatalogUtil().getCategoryIDFromURL();',
            label: [
                {
                    label: 'Category',
                    plural: 'Categories',
                    language: 'en',
                    url: 'itsm_context_help.do?help_resource=CSHelp:Service-Catalog-Categories',
                },
            ],
            referenceTable: 'sc_category',
            referenceQual:
                "javascript:new SNCCatalogUtil().getReferenceQualItem()+ '^sys_class_name!=sc_category_top_n'",
        }),
        sc_catalogs: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
                ts_weight: '5',
            },
            default: 'javascript: new GlobalServiceCatalogUtil().getDefaultCatalog();',
            label: [
                {
                    hint: 'The catalogs this item is associated with',
                    label: 'Catalogs',
                    plural: 'Catalogs',
                    language: 'en',
                    url: 'itsm_context_help.do?help_resource=CSHelp:Service-Catalogs',
                },
            ],
            referenceTable: 'sc_catalog',
            referenceQual: "javascript:'active=true^'+new SNCCatalogUtil().getReferenceQual('');",
        }),
        short_description: TranslatedTextColumn({
            attributes: {
                ts_weight: '15',
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: 'Short description',
            maxLength: 200,
        }),
        description: GenericColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            columnType: 'translated_html',
            label: 'Description',
            maxLength: 8000,
        }),
        meta: StringColumn({
            attributes: {
                ts_weight: '20',
            },
            label: 'Meta',
            maxLength: 4000,
        }),
        location: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                no_text_index: true,
                tree_picker: true,
            },
            label: 'Location',
            referenceTable: 'cmn_location',
        }),
        group: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                no_text_index: true,
            },
            label: [
                {
                    hint: 'Group assigned to fulfill, or complete this task',
                    label: 'Fulfillment group',
                    plural: 'Fulfillment groups',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_user_group',
        }),
        delivery_time: DurationColumn({
            attributes: {
                no_text_index: true,
            },
            default: '2 00:00:00',
            label: 'Delivery time',
            maxLength: 40,
        }),
        model: ReferenceColumn({
            attributes: {
                readonly_clickthrough: true,
            },
            cascadeRule: 'restrict',
            label: 'Model',
            referenceTable: 'cmdb_model',
        }),
        type: StringColumn({
            attributes: {
                no_text_index: true,
            },
            default: 'item',
            dropdown: 'dropdown_with_none',
            label: 'Type',
        }),
        template: ReferenceColumn({
            attributes: {
                ref_qual_elements: 'table_name',
            },
            label: 'Template',
            referenceTable: 'sys_template',
            referenceQual: "javascript:gs.include('CatalogItem');new CatalogItem().getReferenceQual();",
        }),
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
        roles: UserRolesColumn({
            array: true,
            attributes: {
                no_text_index: true,
                record_watcher_blacklist: true,
            },
            label: [
                {
                    hint: 'Who can request this catalog item',
                    label: 'Roles',
                    plural: 'Roles',
                    language: 'en',
                },
            ],
        }),
        delivery_plan: ReferenceColumn({
            default: 'javascript:getDefaultDeliveryPlan()',
            label: [
                {
                    label: 'Execution Plan',
                    plural: 'Execution Plans',
                    language: 'en',
                    url: 'itsm_context_help.do?help_resource=CSHelp:Service-Catalog-Concepts',
                },
            ],
            referenceTable: 'sc_cat_item_delivery_plan',
            referenceQual: 'task_table=sc_task^active=true^EQ',
        }),
        picture: GenericColumn({
            attributes: {
                no_text_index: true,
                pdf_cell_type: 'image',
            },
            columnType: 'user_image',
            label: [
                {
                    hint: 'Recomended 480x480 px',
                    label: 'Picture',
                    plural: 'Pictures',
                    language: 'en',
                },
            ],
        }),
        mobile_picture: GenericColumn({
            attributes: {
                pdf_cell_type: 'image',
            },
            columnType: 'user_image',
            label: [
                {
                    hint: 'Picture to use in listings for the classic mobile UI',
                    label: 'Classic Mobile Picture',
                    plural: 'Classic Mobile Pictures',
                    language: 'en',
                },
            ],
        }),
        mobile_picture_type: StringColumn({
            default: 'use_desktop_picture',
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Type of picture to use in classic mobile UI',
                    label: 'Classic Mobile Picture Type',
                    plural: 'Classic Mobile Picture Types',
                    language: 'en',
                },
            ],
        }),
        mobile_hide_price: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Hide price when the item is listed under a category or search results in the classic mobile UI',
                    label: 'Hide price (classic mobile listings)',
                    plural: 'Hide price (classic mobile listings)',
                    language: 'en',
                },
            ],
        }),
        icon: GenericColumn({
            attributes: {
                no_text_index: true,
                pdf_cell_type: 'image',
            },
            columnType: 'user_image',
            label: [
                {
                    hint: 'Recomended 27x27 px',
                    label: 'Icon',
                    plural: 'Icons',
                    language: 'en',
                },
            ],
        }),
        order: IntegerColumn({
            attributes: {
                no_text_index: true,
            },
            default: '0',
            label: [
                {
                    hint: 'Order this item will use inside of a bundle',
                    label: 'Order',
                    plural: 'Orders',
                    language: 'en',
                },
            ],
        }),
        start_closed: BooleanColumn({
            label: [
                {
                    hint: 'Should contents of this bundle initially be collapsed?',
                    label: 'Start closed',
                    plural: 'Start closed',
                    language: 'en',
                },
            ],
        }),
        no_proceed_checkout: BooleanColumn({
            default: false,
            label: [
                {
                    hint: "If true, the proceed to checkout button won't be available when viewing this item",
                    label: 'No proceed checkout',
                    plural: 'No proceed checkouts',
                    language: 'en',
                },
            ],
        }),
        no_order_now: BooleanColumn({
            default: false,
            label: [
                {
                    hint: "If true, the order now button won't be available when viewing this item",
                    label: 'No order now',
                    plural: 'No order nows',
                    language: 'en',
                },
            ],
        }),
        no_order: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'If true, the item cannot be ordered except via a process guide',
                    label: 'No order',
                    plural: 'No orders',
                    language: 'en',
                },
            ],
        }),
        no_search: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'If true, this item will not show up in search results',
                    label: 'No search',
                    plural: 'No searches',
                    language: 'en',
                },
            ],
        }),
        no_cart: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'If true, this item will not show the current shopping cart or the add to cart button',
                    label: 'No cart',
                    plural: 'No carts',
                    language: 'en',
                },
            ],
        }),
        use_sc_layout: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Using Cart Layout will override the item-specific settings for displaying price, quantity, etc. Unselecting this will render this item according to its individual settings',
                    label: 'Use cart layout',
                    plural: 'Use cart layouts',
                    language: 'en',
                },
            ],
        }),
        delivery_plan_script: GenericColumn({
            attributes: {
                no_text_index: true,
            },
            columnType: 'script_plain',
            label: 'Delivery plan script',
            maxLength: 4000,
        }),
        entitlement_script: GenericColumn({
            columnType: 'script_plain',
            label: 'Entitlement script',
            maxLength: 4000,
        }),
        visible_bundle: BooleanColumn({
            default: true,
            label: 'Visible on Bundles',
        }),
        visible_standalone: BooleanColumn({
            default: true,
            label: 'Visible elsewhere',
        }),
        visible_guide: BooleanColumn({
            default: true,
            label: 'Visible on Guides',
        }),
        omit_price: BooleanColumn({
            default: false,
            label: 'Omit price in cart',
        }),
        no_quantity: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'If true, the quantity selector will not be displayed on the item',
                    label: 'No quantity',
                    plural: 'No quantities',
                    language: 'en',
                },
            ],
        }),
        custom_cart: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                no_text_index: true,
            },
            label: 'Cart',
            referenceTable: 'sys_ui_macro',
        }),
        preview: GenericColumn({
            columnType: 'catalog_preview',
            dynamicValueDefinitions: {
                type: 'calculated_value',
                calculatedValue: `calcItemPreview(current);
function calcItemPreview(current) {
    var popScript = '';
    // Called during zboot so check scriptable object available
    if (typeof(GlideappCatalogURLGenerator) !== 'undefined' && typeof(GlideappCatalogURLGenerator.getItemBaseURLFromGR) === 'function') {
        var url = GlideappCatalogURLGenerator.getItemBaseURLFromGR(current);
        if(url.indexOf('?') != -1)
            url += '&sysparm_preview=true';
        else
            url += '?sysparm_preview=true';
        popScript = 'JavaScript: popupOpenStandard("' + url + '", "summary");';
    }
    return popScript;
}`,
            },
            label: 'Preview link',
            maxLength: 255,
        }),
        cost: DecimalColumn({
            attributes: {
                no_text_index: true,
            },
            default: '0',
            label: 'Cost',
            maxLength: 15,
        }),
        recurring_price: GenericColumn({
            attributes: {
                serializer: 'com.glide.script.PriceXMLSerializer',
                omit_sys_original: true,
            },
            columnType: 'price',
            label: 'Recurring price',
            maxLength: 20,
        }),
        recurring_frequency: ChoiceColumn({
            dropdown: 'dropdown_with_none',
            dynamicValueDefinitions: {
                type: 'choices_from_other_table',
                table: 'sys_frequency',
                field: 'value',
            },
            label: 'Recurring Price Frequency',
        }),
        ordered_item_link: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                no_text_index: true,
            },
            label: [
                {
                    hint: 'Additional link shown on the order summary screen for this item (optional)',
                    label: 'Ordered item link',
                    plural: 'Ordered item links',
                    language: 'en',
                },
            ],
            referenceTable: 'sc_ordered_item_link',
        }),
        vendor: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                no_text_index: true,
                readonly_clickthrough: true,
            },
            label: [
                {
                    hint: 'Catalog entry is for this vendor',
                    label: 'Vendor',
                    plural: 'Vendors',
                    language: 'en',
                },
            ],
            referenceTable: 'core_company',
            referenceQual: 'vendor=true^EQ',
        }),
        availability: StringColumn({
            attributes: {
                no_text_index: true,
            },
            default: 'on_desktop',
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Specify on which platform(s) the catalog item will be available',
                    label: 'Availability',
                    plural: 'Availabilities',
                    language: 'en',
                },
            ],
        }),
        sc_ic_item_staging: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                no_text_index: true,
            },
            label: [
                {
                    hint: 'The Item Designer record this catalog item was created from',
                    label: 'Created from item design',
                    plural: 'Created from item designs',
                    language: 'en',
                },
            ],
            readOnly: true,
            readOnlyOption: 'instance_configured',
            referenceTable: 'sc_ic_item_staging',
        }),
        sc_ic_version: IntegerColumn({
            attributes: {
                no_text_index: true,
            },
            label: [
                {
                    hint: 'The Item Designer version this catalog item was created from',
                    label: 'Published version',
                    plural: 'Published versions',
                    language: 'en',
                },
            ],
            readOnly: true,
            readOnlyOption: 'instance_configured',
        }),
        workflow: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                no_text_index: true,
                ref_contributions: 'show_workflow',
            },
            label: 'Workflow',
            referenceTable: 'wf_workflow',
            referenceQual: "javascript:new SNCCatalogUtil().getActiveWorkFlows('sc_req_item')",
        }),
        show_variable_help_on_load: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Not applicable for Service Portal',
                    label: 'Expand help for all questions',
                    plural: 'Expand help for all questions',
                    language: 'en',
                },
            ],
        }),
        hide_sp: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'To hide the visiblity of an item in Service Portal',
                    label: 'Hide on Service Portal',
                    plural: 'Hide on Service Portals',
                    language: 'en',
                },
            ],
        }),
        display_price_property: StringColumn({
            dynamicValueDefinitions: {
                type: 'calculated_value',
                calculatedValue: `(function calculatedFieldValue(current) {

    return gs.getProperty('glide.sc.price.display', 'non_zero');  // return the calculated value

})(current);`,
            },
            label: 'Display price property',
            readOnly: true,
            readOnlyOption: 'instance_configured',
        }),
        owner: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            default: 'javascript:gs.getUserID()',
            label: 'Owner',
            referenceTable: 'sys_user',
        }),
        secondary_owners: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'Secondary owners',
            referenceTable: 'user_criteria',
        }),
        version: IntegerColumn({
            attributes: {
                no_text_index: true,
            },
            label: 'Version',
            readOnly: true,
            readOnlyOption: 'instance_configured',
        }),
        make_item_non_conversational: BooleanColumn({
            label: 'Make the item non-conversational in VA',
        }),
        name: TranslatedTextColumn({
            attributes: {
                ts_weight: '25',
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: 'Name',
            maxLength: 100,
        }),
        no_attachment_v2: BooleanColumn({
            label: 'Hide Attachment',
        }),
        no_cart_v2: BooleanColumn({
            label: "Hide 'Add to Cart'",
        }),
        mandatory_attachment: BooleanColumn({
            label: 'Mandatory Attachment',
        }),
        no_delivery_time_v2: BooleanColumn({
            label: 'Hide Delivery time',
        }),
        flow_designer_flow: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                no_text_index: true,
            },
            label: 'Flow',
            referenceTable: 'sys_hub_flow',
            referenceQual: 'javascript: new CatalogFlowFilters().getServiceCatalogFlows()',
        }),
        taxonomy_topic: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'primary taxonomy topic for the item',
                    label: 'Taxonomy topic',
                    plural: 'Taxonomy topics',
                    language: 'en',
                },
            ],
            referenceTable: 'topic',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        fulfillment_automation_level: StringColumn({
            default: 'unspecified',
            choices: {
                fully_automated: {
                    label: 'Fully automated',
                    sequence: 3,
                },
                unspecified: {
                    label: 'Unspecified',
                    sequence: 0,
                },
                manual: {
                    label: 'Manual',
                    sequence: 1,
                },
                semi_automated: {
                    label: 'Semi-automated',
                    sequence: 2,
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'Fulfillment automation level',
        }),
    },
    textIndex: true,
})
